import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledContributionContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
});

export const StyledCountryChip = styled.div({
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '32px',
  padding: '4px 12px',
  backgroundColor: '#FFF1C2',
  border: '1px solid #FFF1C2',
  borderRadius: '512px',
  fontFamily: theme.fonts.paragraph,
  fontWeight: 500,
  fontSize: '14px',
  lineHeight: 1.4,
  color: '#141414',
  whiteSpace: 'nowrap',
  userSelect: 'none',
});
